/**
 * SPEC-058: montaje del banner de onboarding en el detalle de captura —
 * misma posición que en el detalle de entrevista (antes de la sección
 * Objetivos) y «Asignar plantilla» abriendo el diálogo de edición de la
 * captura (EditCaptureDialog, con el select «Plantilla de preguntas»), que
 * hasta esta spec solo existía en el listado de Capturas.
 * Generated by QA Dev agent.
 *
 * Arnés heredado de CaptureDetailPage.test.tsx (servicios del spike mockeados
 * + bridge window.api); el comportamiento interno del banner está garantizado
 * por InterviewOnboardingBanner.test.tsx — aquí, el contrato de página.
 */
import { render, screen, waitFor, within, type RenderResult } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { Toaster } from '@/components/ui/sonner'
import { TooltipProvider } from '@/components/ui/tooltip'
import { CaptureDetailPage } from '@/pages/CaptureDetailPage'
import { listAudioInputDevices } from '@/services/captureService'
import { getPermissionsStatus } from '@/services/permissionsService'
import type { Discovery, Interview, InterviewTemplate } from '@/types/domain'
import { installMockApi, type MockApiHandle } from '../../helpers/mockApi'

vi.mock('@/services/permissionsService', () => ({
  getPermissionsStatus: vi.fn(),
  requestMicrophoneAccess: vi.fn(),
  openPrivacySettings: vi.fn()
}))

vi.mock('@/services/captureService', () => ({
  DEFAULT_DEVICE_ID: '__default__',
  acquireMicrophoneStream: vi.fn(),
  acquireSystemAudioStream: vi.fn(),
  listAudioInputDevices: vi.fn(),
  stopStream: vi.fn()
}))

vi.mock('@/services/wavRecorderService', () => ({
  CAPTURE_SAMPLE_RATE: 16000,
  WavRecorderService: class {
    start = vi.fn()
    stop = vi.fn()
    getLevels = vi.fn()
  }
}))

let mockApi: MockApiHandle

const DISCOVERY: Discovery = {
  id: 'd-1',
  name: 'Vertical Sanidad',
  objectives: null,
  createdAt: '2026-07-01T09:00:00.000Z',
  updatedAt: '2026-07-01T09:00:00.000Z'
}

const TEMPLATE: InterviewTemplate = {
  id: 't-1',
  name: 'Guión base',
  phase: null,
  blocks: [],
  createdAt: '2026-07-01T09:00:00.000Z',
  updatedAt: '2026-07-01T09:00:00.000Z'
}

function capture(overrides: Partial<Interview> = {}): Interview {
  return {
    id: 'i-1',
    discoveryId: 'd-1',
    companyId: null,
    contactIds: [],
    interviewGroupId: null,
    templateId: null,
    title: 'Captura sin empresa',
    status: 'draft',
    scriptMarkdown: null,
    objectives: [],
    wavPath: null,
    transcriptPath: null,
    createdAt: '2026-07-10T10:00:00.000Z',
    updatedAt: '2026-07-10T10:00:00.000Z',
    ...overrides
  }
}

function renderDetail(): RenderResult {
  return render(
    <TooltipProvider>
      <MemoryRouter initialEntries={['/captures/i-1']}>
        <Routes>
          <Route path="/captures/:id" element={<CaptureDetailPage />} />
        </Routes>
      </MemoryRouter>
      <Toaster />
    </TooltipProvider>
  )
}

beforeEach(() => {
  vi.clearAllMocks()
  mockApi = installMockApi()
  vi.mocked(mockApi.api.db.getInterview).mockResolvedValue({ ok: true, data: capture() })
  vi.mocked(mockApi.api.db.getDiscovery).mockResolvedValue({ ok: true, data: DISCOVERY })
  vi.mocked(mockApi.api.db.listInterviewTemplates).mockResolvedValue({
    ok: true,
    data: [TEMPLATE]
  })
  vi.mocked(getPermissionsStatus).mockResolvedValue({
    microphone: 'granted',
    systemAudio: 'granted'
  })
  vi.mocked(listAudioInputDevices).mockResolvedValue([])
})

describe('CaptureDetailPage onboarding', () => {
  // SPEC-058 · AC-28: mismo banner y misma posición que en el detalle de
  // entrevista (antes de la sección Objetivos)
  it('renders the onboarding banner before the Objetivos section', async () => {
    renderDetail()

    const banner = await screen.findByTestId('interview-onboarding-banner')
    expect(banner).toHaveAttribute('data-step', '1')
    const objectives = await screen.findByTestId('objectives-section')
    expect(
      banner.compareDocumentPosition(objectives) & Node.DOCUMENT_POSITION_FOLLOWING
    ).toBeTruthy()
  })

  // SPEC-058 · AC-14 (variante captura) + AC-15: EditCaptureDialog con el
  // select «Plantilla de preguntas» y avance al paso 2 al guardar
  it('opens EditCaptureDialog from "Asignar plantilla" and moves to step 2 after saving a template', async () => {
    const withTemplate = capture({ templateId: 't-1' })
    vi.mocked(mockApi.api.db.updateInterview).mockResolvedValue({
      ok: true,
      data: withTemplate
    })
    const user = userEvent.setup()
    renderDetail()

    const banner = await screen.findByTestId('interview-onboarding-banner')
    await user.click(within(banner).getByTestId('onboarding-step-action'))

    const dialog = await screen.findByRole('dialog')
    await user.click(within(dialog).getByRole('combobox', { name: 'Plantilla de preguntas' }))
    await user.click(await screen.findByRole('option', { name: 'Guión base' }))
    await user.click(within(dialog).getByRole('button', { name: 'Guardar' }))

    await waitFor(() =>
      expect(mockApi.api.db.updateInterview).toHaveBeenCalledWith(
        'i-1',
        expect.objectContaining({ templateId: 't-1' })
      )
    )
    await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument())
    await waitFor(() =>
      expect(screen.getByTestId('interview-onboarding-banner')).toHaveAttribute('data-step', '2')
    )
  })
})
